#!/bin/bash
# Task 111-w27-inputs-evm-zone-29 -- meshsim WORKER27: the input pipeline (meshsim inputs-pipeline, wip/inputs/, at 7464b84) rebuilds every input of
# evm-zone-29 from the pinned sources, as on a fresh machine, and proves it identical to the runner's copies in persistent data:
#   deliveries (WORKER9's delivery_writer at jolt-asic-planning fa59d9a, jolt-cpp 88dca85) and the selected windows,
#     against tasks 103/104 (written at 8d546e3, jolt-cpp 821e1bd); the v1.26.1 conversion against 105-107's logged manifests;
#   gold's segment file and jumpmap's outputs against task 109.
# Writes $DATA/w27-inputs (persistent data; about 47 GB), deleted when the comparison passes (owner, 2026-11-05); the runner's
# originals are only read. results/111-w27-inputs-evm-zone-29/: the logs, compare.txt, evm-zone-29.sha256 (the manifest for wip/inputs/manifest/).
# Reboot-safe: scratch (/tmp) and $DATA/w27-inputs are removed at the start, every step stages and marks COMPLETE. ~20 min.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD
RES=$REPO/results/111-w27-inputs-evm-zone-29; mkdir -p "$RES"
# Persistent runner data (Quest PIPELINE.md, "Persistent data on the runner"): ~questrunner/data (owner), writable once the
# unit's ReadWritePaths lists it; else the git-ignored data/ in the queue checkout. Never /tmp (wiped at boot).
DATA=$HOME/data
{ mkdir -p "$DATA" && touch "$DATA/.writable" && rm -f "$DATA/.writable"; } 2>/dev/null || DATA=$REPO/data
mkdir -p "$DATA" || { echo "no writable persistent data directory ($HOME/data, $REPO/data)"; exit 4; }
echo "persistent data: $DATA" | tee "$RES/data_path.txt"
W=/tmp/w27-111; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "3ddbcebf08ff8cf3aaf75c1b88fd5eceb93a2a62ce2c942b42ef55f14c0a00b3" ] || { echo "kit sha256 mismatch (want 3ddbcebf08ff8cf3aaf75c1b88fd5eceb93a2a62ce2c942b42ef55f14c0a00b3)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" && (cd "$W/k" && sha256sum -c --quiet HASHES) || { echo "kit files differ from HASHES"; exit 2; }
cat "$W/k/VERSION"; echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1
I=$W/k/meshsim/wip/inputs; O=$DATA/w27-inputs
[ -e /usr/include/libelf.h ] || [ -e /usr/include/libelf/libelf.h ] || { export LIBELF_PREFIX=$W/k/libelf; echo "no system libelf.h: the kit's"; }
OUT=$O bash "$I/deps.sh" --runtime | tee "$RES/deps.txt"
for p in w9-deliveries/evm-zone-29.COMPLETE w26-jumpmap/evm-zone-29.COMPLETE; do [ -f "$DATA/$p" ] || { echo "the runner's $p is missing (tasks 103/104, 109)"; rm -rf "$W"; exit 2; }; done
rm -rf "$O"; mkdir -p "$O"
AV=$(df -BG --output=avail "$O" | tail -1 | tr -dc 0-9); echo "free at $O: ${AV} GB"
[ "$AV" -ge 60 ] || { echo "need about 47 GB plus margin at $O"; rm -rf "$W"; exit 4; }
T0=$(date +%s)
OUT=$O JAP_DIR=$W/k/jap CLASSES=$W/k/classes GOLD_COMMIT=7ef9039 MESHSIM_COMMIT=7464b84 bash "$I/build.sh" evm-zone 29 2>&1 | tee "$RES/build.log"
BRC=${PIPESTATUS[0]}; echo "build exit $BRC after $(( $(date +%s) - T0 )) s"
cp "$O"/logs/*.log "$RES/" 2>/dev/null; rm -f "$RES"/tracer-build.log
RC=1
if [ $BRC = 0 ]; then
  OUT=$O bash "$I/compare_runner.sh" evm-zone-29 "$DATA" 2>&1 | tee "$RES/compare.txt"; RC=${PIPESTATUS[0]}
  OUT=$O MESHSIM_COMMIT=7464b84 bash "$I/record.sh" evm-zone-29 "Quest 111, the build identical to the runner's copies (compare.txt)" && cp "$I/manifest/evm-zone-29.sha256" "$RES/"
  OUT=$O bash "$I/check.sh" evm-zone-29 | tail -1 | tee -a "$RES/compare.txt"
fi
du -sh "$O" 2>/dev/null | tee "$RES/size.txt"
if [ $RC = 0 ]; then rm -rf "$O"; echo "PASS: $O deleted (the runner's originals stay)"; else echo "FAIL: $O kept for inspection"; fi
rm -rf "$W"
echo "end $(date -u), exit $RC"
exit $RC
